import json
import glob
import re

def extract_json_from_markdown(md_content):
    # This regex matches JSON arrays in the markdown content
    json_pattern = re.compile(r'```json\n(\[.*?\])\n```', re.DOTALL)
    match = json_pattern.search(md_content)
    if match:
        return match.group(1)
    return None

def process_markdown_files(input_pattern, output_file):
    with open(output_file, 'w', encoding='utf-8') as out_f:
        for md_file in glob.glob(input_pattern):
            with open(md_file, 'r', encoding='utf-8') as f:
                content = f.read()

            # Split content into individual examples
            examples = content.split('Text: ')[1:]

            for example in examples:
                parts = example.split('Output:', 1)
                if len(parts) == 2:
                    text = parts[0].strip()
                    json_str = extract_json_from_markdown('Output: ' + parts[1])

                    if json_str:
                        try:
                            entities = json.loads(json_str)
                            record = {
                                "text": text,
                                "entities": entities
                            }
                            out_f.write(json.dumps(record, ensure_ascii=False) + '\n')
                        except json.JSONDecodeError:
                            print(f"Error decoding JSON in file {md_file}")

if __name__ == "__main__":
    process_markdown_files('*.md', 'eval_data.jsonl')


