import json
import glob
import re
from collections import defaultdict

def load_data(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        return [json.loads(line) for line in f]

def calculate_metrics(predicted, gold):
    # Initialize counters
    tp = defaultdict(int)
    fp = defaultdict(int)
    fn = defaultdict(int)

    # Calculate true positives, false positives, and false negatives
    for pred, gold_entities in zip(predicted, gold):
        pred_entities = { (e['text'], e['type']) for e in pred['entities'] }
        gold_entities_set = { (e['text'], e['type']) for e in gold_entities['entities'] }

        for entity in pred_entities:
            if entity in gold_entities_set:
                tp[entity[1]] += 1
            else:
                fp[entity[1]] += 1

        for entity in gold_entities_set:
            if entity not in pred_entities:
                fn[entity[1]] += 1

    # Calculate precision, recall, and F1 for each entity type
    metrics = {}
    for entity_type in set(tp.keys()) | set(fp.keys()) | set(fn.keys()):
        precision = tp[entity_type] / (tp[entity_type] + fp[entity_type]) if (tp[entity_type] + fp[entity_type]) > 0 else 0
        recall = tp[entity_type] / (tp[entity_type] + fn[entity_type]) if (tp[entity_type] + fn[entity_type]) > 0 else 0
        f1 = 2 * (precision * recall) / (precision + recall) if (precision + recall) > 0 else 0

        metrics[entity_type] = {
            'precision': precision,
            'recall': recall,
            'f1': f1,
            'support': tp[entity_type] + fn[entity_type]
        }

    # Calculate micro averages
    total_tp = sum(tp.values())
    total_fp = sum(fp.values())
    total_fn = sum(fn.values())

    micro_precision = total_tp / (total_tp + total_fp) if (total_tp + total_fp) > 0 else 0
    micro_recall = total_tp / (total_tp + total_fn) if (total_tp + total_fn) > 0 else 0
    micro_f1 = 2 * (micro_precision * micro_recall) / (micro_precision + micro_recall) if (micro_precision + micro_recall) > 0 else 0

    metrics['micro_avg'] = {
        'precision': micro_precision,
        'recall': micro_recall,
        'f1': micro_f1,
        'support': total_tp + total_fn
    }

    return metrics

def print_metrics(metrics):
    print("\nEntity Type\tPrecision\tRecall\t\tF1\t\tSupport")
    print("-" * 70)

    for entity_type, values in metrics.items():
        print(f"{entity_type}\t\t{values['precision']:.4f}\t\t{values['recall']:.4f}\t\t{values['f1']:.4f}\t\t{values['support']}")

if __name__ == "__main__":
    # Load the evaluation data
    gold_data = load_data('eval_data.jsonl')

    # Load the model predictions
    predicted_data = load_data('predictions.jsonl')

    # Calculate metrics
    metrics = calculate_metrics(predicted_data, gold_data)

    # Print results
    print_metrics(metrics)


