import json
import requests
import time

def load_data(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        return [json.loads(line) for line in f]

def get_ner_predictions(texts, batch_size=5, max_retries=3):
    url = "http://localhost:11434/api/generate"
    headers = {"Content-Type": "application/json"}

    all_predictions = []

    for i in range(0, len(texts), batch_size):
        batch = texts[i:i + batch_size]
        batch_predictions = []

        for text in batch:
            prompt = f"""You are doing Nepali Named Entity Recognition (EverestNER).Extract entities of these types ONLY: Person, Location, Organization, Date, Event.Return a JSON array ONLY (no markdown, no code fences, no extra text).Schema: [{{"text":"...","type":"Person|Location|Organization|Date|Event"}}]Do NOT return [] unless you are confident there are no entities in the text.

Text: {text}
Output:"""

            data = {
                "model": "everestner",
                "prompt": prompt,
                "format": "json",
                "stream": False
            }

            retries = 0
            success = False

            while retries < max_retries and not success:
                try:
                    response = requests.post(url, headers=headers, json=data, timeout=30)
                    response.raise_for_status()

                    result = response.json()
                    try:
                        entities = json.loads(result['response'])
                        if not isinstance(entities, list):
                            entities = []
                    except json.JSONDecodeError:
                        entities = []

                    batch_predictions.append({
                        "text": text,
                        "entities": entities
                    })
                    success = True

                except requests.exceptions.RequestException as e:
                    retries += 1
                    if retries == max_retries:
                        print(f"Failed to process text after {max_retries} retries: {text[:50]}...")
                        batch_predictions.append({
                            "text": text,
                            "entities": []
                        })
                    else:
                        time.sleep(2 ** retries)  # Exponential backoff

        all_predictions.extend(batch_predictions)
        print(f"Processed {min(i + batch_size, len(texts))} of {len(texts)} texts")

    return all_predictions

def save_predictions(predictions, file_path):
    with open(file_path, 'w', encoding='utf-8') as f:
        for prediction in predictions:
            f.write(json.dumps(prediction, ensure_ascii=False) + '\n')

if __name__ == "__main__":
    # Load the evaluation data
    eval_data = load_data('eval_data.jsonl')
    texts = [item['text'] for item in eval_data]

    # Get predictions
    predictions = get_ner_predictions(texts)

    # Save predictions
    save_predictions(predictions, 'predictions.jsonl')
    print("Predictions saved to predictions.jsonl")

