from flask import Flask, request, jsonify
from transformers import AutoTokenizer, AutoModelForTokenClassification
from transformers import pipeline
import json

app = Flask(__name__)

# Load the model and tokenizer
model_name = "nepalitech/bert-base-nepali-uncased-ner"
tokenizer = AutoTokenizer.from_pretrained(model_name)
model = AutoModelForTokenClassification.from_pretrained(model_name)

# Create a NER pipeline
nlp = pipeline("ner", model=model, tokenizer=tokenizer, aggregation_strategy="simple")

# Define the entity types we want to extract
desired_entity_types = ["PER", "LOC", "ORG", "DATE", "EVENT"]

# Mapping from model's entity labels to our desired types
entity_type_mapping = {
    "PER": "PERSON",
    "LOC": "LOCATION",
    "ORG": "ORGANIZATION",
    "DATE": "DATE",
    "EVENT": "EVENT"
}

def extract_entities(text):
    # Get NER results from the model
    ner_results = nlp(text)

    # Filter and map the results
    entities = []
    for entity in ner_results:
        entity_type = entity['entity_group']
        if entity_type in entity_type_mapping:
            # Clean the text by removing special characters that might have been added
            clean_text = entity['word'].replace("▁", " ").strip()
            entities.append({
                "text": clean_text,
                "type": entity_type_mapping[entity_type]
            })

    return entities

@app.route('/extract_entities', methods=['POST'])
def extract_entities_endpoint():
    data = request.get_json()
    text = data.get('text', '')

    if not text:
        return jsonify([])

    entities = extract_entities(text)

    # Return empty array only if we're confident there are no entities
    if not entities:
        return jsonify([])
    else:
        return jsonify(entities)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

