import json
import os
from typing import List, Dict, Any
from openai import OpenAI
from dotenv import load_dotenv

load_dotenv()

client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

def extract_entities(text: str) -> List[Dict[str, Any]]:
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {
                "role": "system",
                "content": "You are doing Nepali Named Entity Recognition (EverestNER). Extract entities of these types ONLY: Person, Location, Organization, Date, Event. Return a JSON array ONLY (no markdown, no code fences, no extra text). Schema: [{\"text\":\"...\",\"type\":\"Person|Location|Organization|Date|Event\"}]. Do NOT return [] unless you are confident there are no entities in the text."
            },
            {
                "role": "user",
                "content": f"Text: {text}"
            }
        ],
        temperature=0.0,
    )

    try:
        entities = json.loads(response.choices[0].message.content)
        return entities
    except json.JSONDecodeError:
        return []

def process_file(input_file: str, output_file: str) -> None:
    with open(input_file, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    results = []
    for line in lines:
        line = line.strip()
        if line:
            entities = extract_entities(line)
            results.append({
                "text": line,
                "entities": entities
            })

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False, indent=2)

if __name__ == "__main__":
    input_file = "input.txt"
    output_file = "output.json"
    process_file(input_file, output_file)

