import json
import os
import sys
from typing import List, Dict

from dotenv import load_dotenv
from openai import OpenAI

load_dotenv()

client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

def extract_entities(text: str) -> List[Dict[str, str]]:
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {
                "role": "system",
                "content": "You are doing Nepali Named Entity Recognition (EverestNER). Extract entities of these types ONLY: Person, Location, Organization, Date, Event. Return a JSON array ONLY (no markdown, no code fences, no extra text). Schema: [{\"text\":\"...\",\"type\":\"Person|Location|Organization|Date|Event\"}]. Do NOT return [] unless you are confident there are no entities in the text.",
            },
            {
                "role": "user",
                "content": f"Text: {text}",
            },
        ],
        temperature=0.0,
    )

    return json.loads(response.choices[0].message.content)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python run.py <text>")
        sys.exit(1)

    text = sys.argv[1]
    entities = extract_entities(text)
    print(json.dumps(entities, ensure_ascii=False))

