from flask import Flask, request, jsonify
from transformers import AutoTokenizer, AutoModelForTokenClassification
from transformers import pipeline
import json

app = Flask(__name__)

# Load the model and tokenizer
tokenizer = AutoTokenizer.from_pretrained("sauravjoshi/sauravjoshi/EverestNER")
model = AutoModelForTokenClassification.from_pretrained("sauravjoshi/sauravjoshi/EverestNER")

# Create a NER pipeline
nlp = pipeline("ner", model=model, tokenizer=tokenizer, aggregation_strategy="simple")

# Define the entity types we are interested in
entity_types = ["PERSON", "LOCATION", "ORGANIZATION", "DATE", "EVENT"]

@app.route('/extract_entities', methods=['POST'])
def extract_entities():
    data = request.get_json()
    text = data.get('text', '')

    if not text:
        return jsonify([])

    # Get NER results
    ner_results = nlp(text)

    # Filter and format the results
    entities = []
    for entity in ner_results:
        if entity['entity_group'] in entity_types:
            entities.append({
                "text": entity['word'],
                "type": entity['entity_group']
            })

    return jsonify(entities)

if __name__ == '__main__':
    app.run(debug=True)

